# Keys that hold a shell command across every agent CLI schema. Discovered
# empirically, not guessed: Claude Code uses input.command (str), Codex uses
# command (argv list, e.g. ["bash","-lc","..."]), Copilot/Factory use cmd.
# Deliberately excludes output/stdout/aggregated_output — command RESULTS are
# where the false positives live (help text, diffs, grep hits).
CMD_KEYS = {"command", "cmd", "script", "shell_command", "commandline"}
SKIP_KEYS = {"output", "stdout", "stderr", "aggregated_output", "formatted_output",
             "result", "content", "text", "message", "thinking"}

def bash_commands(rec, _depth=0):
    """Yield every string that a shell actually executed, schema-agnostically.

    Walks the whole record looking for command-bearing keys rather than
    enumerating each agent's tool_use shape."""
    if _depth > 12:
        return
    if isinstance(rec, dict):
        for k, v in rec.items():
            kl = k.lower()
            if kl in SKIP_KEYS:
                continue
            if kl in CMD_KEYS:
                if isinstance(v, str):
                    yield v
                elif isinstance(v, list) and all(isinstance(x, str) for x in v):
                    # argv form: ["bash","-lc","<script>"] -> take the script
                    yield v[-1] if len(v) > 2 and v[0] in ("bash", "sh", "zsh") else " ".join(v)
                    continue
            if kl == "arguments" and isinstance(v, str):
                try:
                    yield from bash_commands(json.loads(v), _depth + 1)
                except Exception:
                    pass
                continue
            yield from bash_commands(v, _depth + 1)
    elif isinstance(rec, list):
        for x in rec:
            yield from bash_commands(x, _depth + 1)

