190	type agentHelpFlagJSON struct {
191		Name      string `json:"name"`
192		Shorthand string `json:"shorthand,omitempty"`
193		Type      string `json:"type"`
194		Default   string `json:"default,omitempty"`
195		Usage     string `json:"usage"`
196	}
197	
198	type agentHelpSubcommandJSON struct {
199		Name  string `json:"name"`
200		Short string `json:"short"`
201	}
202	
203	type agentHelpJSON struct {
204		Command     string                    `json:"command"`
205		Short       string                    `json:"short,omitempty"`
206		Long        string                    `json:"long,omitempty"`
207		Example     string                    `json:"example,omitempty"`
208		Repo        string                    `json:"repo,omitempty"`
209		Flags       []agentHelpFlagJSON       `json:"flags,omitempty"`
210		Subcommands []agentHelpSubcommandJSON `json:"subcommands,omitempty"`
211	}
212	
213	// renderAgentHelpJSON renders the structured form of a command node.
214	func renderAgentHelpJSON(rootCmd, target *cobra.Command, repoLine string, trailsEnabled bool) (string, error) {
215		doc := agentHelpJSON{
216			Command: target.CommandPath(),
217			Short:   target.Short,
218			Long:    strings.TrimSpace(target.Long),
219			Example: strings.TrimSpace(target.Example),
220			Repo:    repoLine,
221		}
222		if target != rootCmd {
223			collect := func(fs *flag.FlagSet) {
224				fs.VisitAll(func(f *flag.Flag) {
225					if f.Hidden {
226						return
227					}
228					doc.Flags = append(doc.Flags, agentHelpFlagJSON{
229						Name:      f.Name,
230						Shorthand: f.Shorthand,
231						Type:      f.Value.Type(),
232						Default:   f.DefValue,
233						Usage:     f.Usage,
234					})
235				})
236			}
237			collect(target.LocalFlags())
238			collect(target.InheritedFlags())
239		}
240		for _, sub := range agentHelpCommands(target, trailsEnabled) {
241			doc.Subcommands = append(doc.Subcommands, agentHelpSubcommandJSON{Name: sub.Name(), Short: sub.Short})
242		}
243		b, err := json.MarshalIndent(doc, "", "  ")
244		if err != nil {
245			return "", fmt.Errorf("marshal agent-help json: %w", err)
246		}
247		return string(b) + "\n", nil
248	}
249	
250	// isAgentHelpAdvertised reports whether sub should be exposed to agents through
251	// agent-help. The listing AND the drill-down resolver share this predicate so
252	// the drillable surface always matches the advertised surface: visible commands
253	// plus hidden commands that opt in via agentHelpAnnotation, minus the help
254	// command, deprecated commands, and (when trails are disabled) trail-gated ones.
255	func isAgentHelpAdvertised(sub *cobra.Command, trailsEnabled bool) bool {
256		if sub.Name() == "help" || sub.Name() == "agent-help" || sub.Deprecated != "" {
257			return false
258		}
259		if sub.Hidden && sub.Annotations[agentHelpAnnotation] != agentHelpAnnotationEnabled {
260			return false
261		}
262		if !trailsEnabled && sub.Annotations[agentHelpRequiresTrailsAnnotation] == agentHelpAnnotationEnabled {
263			return false
264		}
265		return true
266	}
267	
268	// agentHelpCommands returns the child commands to advertise to agents.
269	func agentHelpCommands(parent *cobra.Command, trailsEnabled bool) []*cobra.Command {
270		var out []*cobra.Command
271		for _, sub := range parent.Commands() {
272			if isAgentHelpAdvertised(sub, trailsEnabled) {
273				out = append(out, sub)
274			}
275		}
276		return out
277	}
278	
279	// agentHelpRepoBlock formats the auto-detected repo line, degrading gracefully
280	// when the repo can't be resolved (no origin / detached HEAD) rather than
281	// implying a repo that isn't there.
282	func agentHelpRepoBlock(repoLine string) string {
283		// Defense-in-depth: this line is emitted as plain text into agent context and
284		// the user's terminal. A crafted origin URL's control characters (newline,
285		// ANSI escapes) are rejected upstream in gitremote, but never let one reach
286		// this plain-text sink — degrade to the not-detectable message instead.
287		if strings.TrimSpace(repoLine) == "" || strings.IndexFunc(repoLine, unicode.IsControl) >= 0 {
288			return "Current repo: not auto-detectable here (no origin remote / detached HEAD); pass --repo explicitly.\n"
289		}
290		return "Current repo: " + repoLine + "  (auto-detected from origin; pass --repo only for a DIFFERENT repo)\n"
291	}
292	
293	// renderAgentHelpCommand renders one resolved command node for an agent: its
294	// path + Short, its Long description, the auto-detected repo line, its live flag
295	// usages (hidden flags are skipped by cobra), and its advertised subcommands.
296	func renderAgentHelpCommand(cmd *cobra.Command, repoLine string, trailsEnabled bool) string {
297		var b strings.Builder
298		fmt.Fprintf(&b, "%s — %s\n", cmd.CommandPath(), cmd.Short)
299		if long := strings.TrimSpace(cmd.Long); long != "" && long != strings.TrimSpace(cmd.Short) {
300			b.WriteString(long)
301			b.WriteString("\n")
302		}
303		if example := strings.TrimSpace(cmd.Example); example != "" {
304			b.WriteString("\nExamples:\n")
305			b.WriteString(example)
306			b.WriteString("\n")
307		}
308		b.WriteString("\n")
309		b.WriteString(agentHelpRepoBlock(repoLine))
310	
311		// LocalFlags()/InheritedFlags() trigger cobra's persistent-flag merge (plain
312		// Flags() does not without Execute) and skip hidden flags in FlagUsages.
313		if usages := strings.TrimRight(cmd.LocalFlags().FlagUsages(), "\n"); usages != "" {
314			b.WriteString("\nFlags:\n")
315			b.WriteString(usages)
316			b.WriteString("\n")
317		}
318		if usages := strings.TrimRight(cmd.InheritedFlags().FlagUsages(), "\n"); usages != "" {
319			b.WriteString("\nInherited flags:\n")
320			b.WriteString(usages)
321			b.WriteString("\n")
322		}
323	
324		if subs := agentHelpCommands(cmd, trailsEnabled); len(subs) > 0 {
325			names := make([]string, 0, len(subs))
326			for _, sub := range subs {
327				names = append(names, sub.Name())
328			}
329			fmt.Fprintf(&b, "\nSubcommands: %s\n", strings.Join(names, " · "))
330			fmt.Fprintf(&b, "Next:  entire agent-help %s <subcommand>\n", strings.TrimPrefix(cmd.CommandPath(), cmd.Root().Name()+" "))
331		}
332		return b.String()
333	}
334	
335	// renderAgentHelpTop renders the top-level agent-facing overview: the curated
336	// intro + rule, the auto-detected repo line, and a live map of the advertised
337	// commands (their Short help), ending with the drill-down pointer.
338	func renderAgentHelpTop(rootCmd *cobra.Command, repoLine string, trailsEnabled bool) string {
339		var b strings.Builder
340		b.WriteString(agentHelpOverview)
341		b.WriteString("\n\n")
342		b.WriteString(agentHelpRepoBlock(repoLine))
343		b.WriteString("\nWhen to use entire:\n")
344		for _, sub := range agentHelpCommands(rootCmd, trailsEnabled) {
345			fmt.Fprintf(&b, "  %-12s %s\n", sub.Name(), sub.Short)
346		}
347		// Use an example command that is actually advertised here (trail is gated on
348		// trails being enabled), so we never point at a command the agent can't use.
349		example := "checkpoint"
350		if trailsEnabled {
351			example = "trail"
352		}
353		fmt.Fprintf(&b, "\nDrill in for exact, currently-installed flags:  entire agent-help <command>  (e.g. entire agent-help %s)\n", example)
354		b.WriteString("Add --json for structured output.\n")
355		return b.String()
356	}
